from pathlib import Path
from playwright.sync_api import sync_playwright
import json
root=Path(__file__).resolve().parents[1];script=(root/'gc-wallet-companion/merchant-assist.js').read_text()
fixture='''<form id="check-gift-card-balance-form"><input name="gc-number"><input name="securitycode"><button type="submit">Check Balance</button></form><script>window.submissions=0;window.dismissals=0;window.kind='valid';window.after='normal';document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();submissions++;if(kind==='noresponse')return;const d=document.createElement('div');d.setAttribute('role','dialog');d.innerHTML=kind==='blocked'?'<h2>Challenge</h2>':'<h2>Gift card balance</h2><p class="cardnumber">Ending in '+(kind==='mismatch'?'9999':document.querySelector('[name="gc-number"]').value.replace(/\\D/g,'').slice(-4))+'</p><p class="balance">Balance: $0.00</p><button>Check another card balance</button>';if(d.querySelector('button'))d.querySelector('button').onclick=()=>{dismissals++;if(after==='challenge'){d.remove();const x=document.createElement('div');x.setAttribute('role','dialog');x.textContent='Challenge';document.body.append(x);return;}if(after==='stuck')return;setTimeout(()=>{d.remove();document.querySelector('[name="gc-number"]').value='';document.querySelector('[name="securitycode"]').value='';},150);};document.body.append(d);});</script>'''
checks=[]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page();page.route('**/*',lambda r:r.abort());page.set_content(fixture)
 page.add_script_tag(content="window.chrome={runtime:{id:'fixture',onMessage:{addListener:f=>window.assist=f}}};window.send=(m,id='fixture')=>new Promise(resolve=>{const async=assist(m,{id},resolve);if(async!==true)setTimeout(()=>resolve(null),0);});")
 page.add_script_tag(content="(function(location){"+script+"})({href:'https://www.walmart.ca/en/account/giftcards/balance'})")
 token='11111111-1111-4111-8111-111111111111';fill={'type':'assist-fill','number':'0000000000001111','pin':'0001','token':token};read={'type':'assist-read','token':token};finish={'type':'assist-finish','token':token}
 send=lambda msg:page.evaluate('(m)=>send(m)',msg)
 assert page.evaluate('(m)=>send(m,"untrusted")',fill) is None;assert not page.locator('[name=gc-number]').input_value();checks.append('reject foreign sender')
 assert send(fill)=={'ok':True};assert page.locator('[name=gc-number]').input_value().replace(' ','')=='0000000000001111';assert page.locator('[name=securitycode]').input_value()=='0001';assert page.evaluate('submissions')==0;checks.append('autofill and no submit')
 assert send(finish)['state']=='unavailable';assert page.evaluate('dismissals')==0;checks.append('cannot dismiss before matched capture')
 assert send(read)['state']=='waiting';page.evaluate("document.querySelector('button').click()");assert send(read)['state']=='blocked';checks.append('untrusted submit cannot save')
 page.evaluate("document.querySelector('[role=dialog]').remove()");assert send(fill)['ok'];page.get_by_role('button',name='Check Balance').click();assert send(read)=={'ok':True,'state':'observed','balance':'0.00'};assert send(read)['state']=='awaiting-save';checks.append('trusted exact match captured once')
 assert send(finish)=={'ok':True,'state':'ready'};assert page.evaluate('dismissals')==1;assert not page.locator('[name=gc-number]').input_value();assert send(finish)['state']=='unavailable';checks.append('matched saved dialog dismissed and form ready')
 assert send(fill)['ok'];page.get_by_role('button',name='Check Balance').click();assert send(read)['state']=='observed';page.evaluate("document.querySelector('.balance').textContent='Balance: $1.00'");assert send(finish)['state']=='blocked';assert page.evaluate('dismissals')==1;checks.append('changed dialog not dismissed')
 for kind,state in [('mismatch','mismatch'),('blocked','blocked')]:
  page.evaluate("document.querySelector('[role=dialog]').remove()");assert send(fill)['ok'];page.evaluate('(v)=>kind=v',kind);page.get_by_role('button',name='Check Balance').click();assert send(read)['state']==state;assert send(finish)['state']=='unavailable';checks.append(state+' stops capture and dismissal')
 page.evaluate("document.querySelector('[role=dialog]').remove();kind='valid';after='challenge'");assert send(fill)['ok'];page.get_by_role('button',name='Check Balance').click();assert send(read)['state']=='observed';assert send(finish)['state']=='blocked';assert not send(fill)['ok'];checks.append('new challenge after dismissal blocks next fill')
 page.evaluate("document.querySelector('[role=dialog]').remove();after='normal'");assert send(fill)['ok'];page.locator('[name=securitycode]').fill('0002');assert send(read)['state']=='unavailable';checks.append('field edit invalidates capture')
 assert send(fill)['ok'];assert send({'type':'assist-reset','token':token})['ok'];assert send(read)['state']=='unavailable';assert not send(fill)['ok'];checks.append('cancel prevents late fill')
 assert page.evaluate('submissions')==6;checks.append('no submissions from fill, polling or advance')
 token2='22222222-2222-4222-8222-222222222222';f2={**fill,'token':token2};r2={'type':'assist-read','token':token2};submit={'type':'assist-submit','token':token2};finish2={'type':'assist-finish','token':token2}
 assert send(f2)['ok'];assert send(submit)['ok'];assert not send(submit)['ok'];assert page.evaluate('submissions')==7;assert send(r2)['state']=='observed';assert send(finish2)['ok'];assert page.evaluate('submissions')==7;checks.append('explicit overlay submission exactly once; no next submission')
 page.evaluate("kind='noresponse'");page.clock.install();assert send(f2)['ok'];assert send(submit)['ok'];assert send(r2)['state']=='waiting';page.clock.fast_forward(31000);assert send(r2)['state']=='timeout';assert not send(submit)['ok'];assert page.evaluate('submissions')==8;checks.append('30-second timeout without retry');b.close()
(root/'tests/assisted-fixture-results.json').write_text(json.dumps({'checks':checks,'scope':'offline Chromium fixture, mocked runtime messaging, actual trusted clicks','nativeExtension':False},indent=2)+'\n');print('Assisted merchant fixture: '+str(len(checks))+' checks PASS')
